import{_ as a,o as i,c as o,ag as r}from"./chunks/framework.BSsJcWLc.js";const p=JSON.parse('{"title":"Changelog","description":"","frontmatter":{},"headers":[],"relativePath":"changelog.md","filePath":"changelog.md"}'),t={name:"changelog.md"};function l(n,e,d,s,c,h){return i(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="changelog" tabindex="-1">Changelog <a class="header-anchor" href="#changelog" aria-label="Permalink to &quot;Changelog&quot;">​</a></h1><p>All notable changes to Dendrite will be documented here.</p><hr><h2 id="v0-10-0-web-platform-migration" tabindex="-1">v0.10.0 - Web Platform Migration <a class="header-anchor" href="#v0-10-0-web-platform-migration" aria-label="Permalink to &quot;v0.10.0 - Web Platform Migration&quot;">​</a></h2><p>Full platform migration from PyQt6 desktop app to FastAPI + Vue 3 SPA. All four auxiliary tools (Dashboard, Stream Manager, ML Workbench, DB Explorer) are now integrated into a single web application.</p><h3 id="platform" tabindex="-1">Platform <a class="header-anchor" href="#platform" aria-label="Permalink to &quot;Platform&quot;">​</a></h3><ul><li>FastAPI backend with REST API for configuration/control and WebSocket for real-time data</li><li>Vue 3 SPA with Pinia stores, Tailwind CSS, dark theme with custom design tokens</li><li>Four WS channels: <code>/ws/telemetry</code> (1Hz JSON), <code>/ws/visualization</code> (30fps msgpack), <code>/ws/mode_data</code> (msgpack), <code>/ws/training</code> (JSON)</li><li>Singleton service layer (<code>deps.py</code>) with dependency injection</li><li><code>QueueBridge</code> drains multiprocessing queues and fans out to WebSocket subscribers</li><li>Single-port production deployment (FastAPI serves built frontend static files)</li></ul><h3 id="processing-pipeline" tabindex="-1">Processing Pipeline <a class="header-anchor" href="#processing-pipeline" aria-label="Permalink to &quot;Processing Pipeline&quot;">​</a></h3><ul><li>Dynamic mode control: REST API for adding, removing, starting, and stopping modes at runtime without restarting the pipeline</li><li>Online bad channel interpolation via correlation-based weighting (no electrode positions required)</li><li><code>SharedRingBuffer</code> replaces per-mode queues — all consumers read shared memory directly (zero-copy, no pickle overhead)</li><li>Per-mode lazy-init preprocessing (<code>BaseMode._setup_preprocessor()</code>, <code>SamplePreprocessor</code>)</li><li>Visualization bridge reads ring buffer directly, applies preprocessing + channel quality monitoring</li><li>Bad channel tracking via SharedState with stable rereferencing (no dynamic exclusion to prevent step artifacts)</li><li>Epoch quality control: auto-reject NaN, flat, and extreme outlier epochs during training data prep</li><li><code>ComponentStateMachine</code> for process lifecycle management</li><li>Dead mode detection and automatic cleanup via <code>check_mode_health()</code></li><li>Normalized DAQ latency key to flat <code>latency_ms</code> + <code>stream_type</code></li><li>Lazy ML imports (deferred torch loading in decoders)</li><li>Multi-modality refactoring: removed hardcoded EEG references, generalized stream-modality hierarchy</li><li>Online training from live recording data via training queue (sync mode → MLService)</li></ul><h3 id="data-storage" tabindex="-1">Data &amp; Storage <a class="header-anchor" href="#data-storage" aria-label="Permalink to &quot;Data &amp; Storage&quot;">​</a></h3><ul><li><code>DataSaver</code> (SWMR HDF5) is the single writer for session-wide data + epoch storage</li><li>Shared memory ring buffers (<code>SharedRingBuffer</code>) for zero-copy DAQ → consumer data flow</li><li><code>ReplayStreamer</code> for offline stream replay (replaces <code>OfflineDataStreamer</code>)</li><li>Dataset import from internal DB and MOABB</li><li>Recording protection (prevent deletion during active sessions)</li><li>Continuous channel quality monitoring (MAD-based, replaces one-shot detector)</li></ul><h3 id="ml-workbench" tabindex="-1">ML Workbench <a class="header-anchor" href="#ml-workbench" aria-label="Permalink to &quot;ML Workbench&quot;">​</a></h3><ul><li>Online training offloaded to subprocess</li><li>Recording-based training: load recordings from database with RecordingBrowser</li><li>Job management: save decoder from completed job, delete job records</li></ul><h3 id="ui-ux" tabindex="-1">UI/UX <a class="header-anchor" href="#ui-ux" aria-label="Permalink to &quot;UI/UX&quot;">​</a></h3><ul><li>Embedded live dashboard (EEG, PSD, events, mode plots) directly in Control page</li><li>Telemetry sidebar auto-shows on recording start, hidden when idle</li><li>Stream manager integrated with indicator in nav showing active offline stream count</li><li>Data explorer integrated with full CRUD for studies, recordings, decoders, datasets</li><li>Channel quality summary and total system CPU/RAM in telemetry sidebar</li><li>Core process PIDs (DAQ, DataSaver, MetricsSaver) tracked in telemetry resources</li><li>Mode info panels in dashboard with color-coded latency (Proc/Inf)</li><li>CreateStudyDialog with folder import for bulk .h5 recording registration</li><li>RecordingBrowser component for ML training data selection from database</li><li>Toast notifications and tab close warning during recording</li><li>StreamSetupDialog UX improvements</li></ul><hr><h2 id="v0-9-0-initial-release" tabindex="-1">v0.9.0 - Initial Release <a class="header-anchor" href="#v0-9-0-initial-release" aria-label="Permalink to &quot;v0.9.0 - Initial Release&quot;">​</a></h2><p>PyQt6 desktop application with real-time EEG/BCI processing pipeline. Three composable processing modes (Synchronous, Asynchronous, Neurofeedback), multi-modality LSL data acquisition, HDF5/SQLite storage, full ML layer (EEGNet, Braindecode, CSP+LDA/SVM), and output over LSL, TCP, ZeroMQ, and ROS2. Separate auxiliary tools: Dashboard, Stream Manager, ML Workbench, DB Explorer.</p>',18)])])}const g=a(t,[["render",l]]);export{p as __pageData,g as default};
